const crypto = require('node:crypto');
const path = require('node:path');
const { DatabaseSync } = require('node:sqlite');
const express = require('express');

const app = express();
const port = Number(process.env.PORT) || 3000;
const startedAt = Date.now();
const maxAttempts = 12;
const initialRetryDelayMs = 1000;
const maxRetryDelayMs = 60 * 60 * 1000;
const deliveryTimeoutMs = 5000;
const pollIntervalMs = 250;
const maxConcurrentDeliveries = 10;
const databasePath = path.resolve(process.env.WEBHOOK_DB_PATH || 'webhooks.sqlite');
const database = new DatabaseSync(databasePath);
const activeDeliveries = new Set();

database.exec(`
  PRAGMA journal_mode = WAL;
  PRAGMA foreign_keys = ON;
  PRAGMA busy_timeout = 5000;

  CREATE TABLE IF NOT EXISTS subscriptions (
    id TEXT PRIMARY KEY,
    endpoint_url TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
  );

  CREATE TABLE IF NOT EXISTS events (
    id TEXT PRIMARY KEY,
    subscription_id TEXT NOT NULL REFERENCES subscriptions(id),
    endpoint_url TEXT NOT NULL,
    payload TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('pending', 'delivering', 'delivered', 'failed')),
    attempt_count INTEGER NOT NULL DEFAULT 0,
    next_attempt_at INTEGER NOT NULL,
    last_error TEXT,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    delivered_at INTEGER
  );

  CREATE INDEX IF NOT EXISTS events_due_idx
    ON events(status, next_attempt_at);
`);

// A process may stop during a request. Retry those deliveries after restart.
database.prepare(`
  UPDATE events SET status = 'pending', updated_at = ?
  WHERE status = 'delivering'
`).run(Date.now());

app.use(express.json({ limit: '1mb' }));

app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.url}`);
  next();
});

app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    uptimeSeconds: Math.floor((Date.now() - startedAt) / 1000),
    timestamp: new Date().toISOString(),
  });
});

app.post('/subscriptions', (req, res) => {
  const { subscriptionId, endpointUrl } = req.body || {};
  if (typeof subscriptionId !== 'string' || subscriptionId.trim() === '') {
    return res.status(400).json({ error: 'subscriptionId must be a non-empty string' });
  }
  if (typeof endpointUrl !== 'string') {
    return res.status(400).json({ error: 'endpointUrl must be a valid HTTP or HTTPS URL' });
  }

  let parsedUrl;
  try {
    parsedUrl = new URL(endpointUrl);
  } catch {
    return res.status(400).json({ error: 'endpointUrl must be a valid HTTP or HTTPS URL' });
  }

  if (!['http:', 'https:'].includes(parsedUrl.protocol) || parsedUrl.username || parsedUrl.password) {
    return res.status(400).json({ error: 'endpointUrl must be a valid HTTP or HTTPS URL without credentials' });
  }

  const now = Date.now();
  database.prepare(`
    INSERT INTO subscriptions (id, endpoint_url, created_at, updated_at)
    VALUES (?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET endpoint_url = excluded.endpoint_url, updated_at = excluded.updated_at
  `).run(subscriptionId.trim(), parsedUrl.toString(), now, now);

  res.status(201).json({
    subscriptionId: subscriptionId.trim(),
    endpointUrl: parsedUrl.toString(),
  });
});

app.post('/events', (req, res) => {
  const { subscriptionId } = req.body || {};
  if (typeof subscriptionId !== 'string' || subscriptionId.trim() === '') {
    return res.status(400).json({ error: 'subscriptionId must be a non-empty string' });
  }
  if (!Object.prototype.hasOwnProperty.call(req.body, 'payload')) {
    return res.status(400).json({ error: 'payload is required' });
  }

  const subscription = database.prepare(`
    SELECT endpoint_url FROM subscriptions WHERE id = ?
  `).get(subscriptionId.trim());
  if (!subscription) {
    return res.status(404).json({ error: 'Subscription not found' });
  }

  const id = crypto.randomUUID();
  const now = Date.now();
  database.prepare(`
    INSERT INTO events (
      id, subscription_id, endpoint_url, payload, status, next_attempt_at, created_at, updated_at
    ) VALUES (?, ?, ?, ?, 'pending', ?, ?, ?)
  `).run(id, subscriptionId.trim(), subscription.endpoint_url, JSON.stringify(req.body.payload), now, now, now);

  res.status(202).json({ eventId: id, status: 'pending' });
});

app.get('/events/:eventId', (req, res) => {
  const event = database.prepare(`
    SELECT id, subscription_id AS subscriptionId, status, attempt_count AS attemptCount,
      next_attempt_at AS nextAttemptAt, last_error AS lastError, created_at AS createdAt,
      updated_at AS updatedAt, delivered_at AS deliveredAt
    FROM events WHERE id = ?
  `).get(req.params.eventId);

  if (!event) {
    return res.status(404).json({ error: 'Event not found' });
  }

  if (event.status === 'delivering') {
    event.status = 'pending';
  }
  res.status(200).json(event);
});

app.post('/events/:eventId/retry', (req, res) => {
  const now = Date.now();
  const result = database.prepare(`
    UPDATE events SET status = 'pending', attempt_count = 0, next_attempt_at = ?,
      last_error = NULL, updated_at = ?, delivered_at = NULL
    WHERE id = ? AND status = 'failed'
  `).run(now, now, req.params.eventId);

  if (result.changes === 0) {
    const exists = database.prepare('SELECT status FROM events WHERE id = ?').get(req.params.eventId);
    if (!exists) {
      return res.status(404).json({ error: 'Event not found' });
    }
    return res.status(409).json({ error: 'Only failed events can be retried', status: exists.status });
  }

  res.status(202).json({ eventId: req.params.eventId, status: 'pending' });
});

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist',
  });
});

app.use((err, req, res, next) => {
  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid JSON body',
    });
  }

  if (err.type === 'entity.too.large') {
    return res.status(413).json({ error: 'Payload Too Large', message: 'Request body exceeds 1mb' });
  }

  const status = err.status || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  console.error('Unhandled error:', err.message, { url: req.url, method: req.method });

  res.status(status).json({
    error: status >= 500 ? 'Internal Server Error' : err.name || 'Error',
    message: isProduction && status >= 500 ? 'An unexpected error occurred' : err.message,
  });
});

function retryDelay(attemptCount) {
  return Math.min(initialRetryDelayMs * (2 ** (attemptCount - 1)), maxRetryDelayMs);
}

async function deliver(event) {
  const now = Date.now();
  const attemptCount = event.attempt_count + 1;
  const claimed = database.prepare(`
    UPDATE events SET status = 'delivering', attempt_count = ?, updated_at = ?
    WHERE id = ? AND status = 'pending'
  `).run(attemptCount, now, event.id);
  if (claimed.changes === 0) {
    return;
  }

  try {
    const response = await fetch(event.endpoint_url, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'idempotency-key': event.id,
        'x-webhook-event-id': event.id,
        'x-webhook-subscription-id': event.subscription_id,
      },
      body: event.payload,
      signal: AbortSignal.timeout(deliveryTimeoutMs),
    });

    if (!response.ok) {
      throw new Error(`Endpoint returned HTTP ${response.status}`);
    }

    const deliveredAt = Date.now();
    database.prepare(`
      UPDATE events SET status = 'delivered', last_error = NULL, delivered_at = ?, updated_at = ?
      WHERE id = ?
    `).run(deliveredAt, deliveredAt, event.id);
  } catch (error) {
    const failedAt = Date.now();
    const isFailed = attemptCount >= maxAttempts;
    const nextAttemptAt = isFailed ? failedAt : failedAt + retryDelay(attemptCount);
    database.prepare(`
      UPDATE events SET status = ?, next_attempt_at = ?, last_error = ?, updated_at = ?
      WHERE id = ?
    `).run(isFailed ? 'failed' : 'pending', nextAttemptAt, error.message, failedAt, event.id);
    console.error(`Webhook delivery ${event.id} failed (attempt ${attemptCount}/${maxAttempts}): ${error.message}`);
  }
}

let dispatching = false;
async function dispatchDueEvents() {
  if (dispatching) {
    return;
  }
  dispatching = true;
  try {
    const availableSlots = maxConcurrentDeliveries - activeDeliveries.size;
    if (availableSlots <= 0) {
      return;
    }

    const dueEvents = database.prepare(`
      SELECT id, subscription_id, endpoint_url, payload, attempt_count
      FROM events
      WHERE status = 'pending' AND next_attempt_at <= ?
      ORDER BY created_at
      LIMIT ?
    `).all(Date.now(), availableSlots);

    const deliveries = dueEvents.map((event) => {
      const delivery = deliver(event).finally(() => activeDeliveries.delete(delivery));
      activeDeliveries.add(delivery);
      return delivery;
    });
    await Promise.all(deliveries);
  } catch (error) {
    console.error('Failed to dispatch webhook events:', error);
  } finally {
    dispatching = false;
  }
}

let server;
let pollingTimer;
function start() {
  if (server) {
    return server;
  }
  server = app.listen(port, () => {
    console.log(`Server running on http://localhost:${port}`);
    console.log(`Webhook database: ${databasePath}`);
  });
  pollingTimer = setInterval(dispatchDueEvents, pollIntervalMs);
  return server;
}

async function shutdown(signal) {
  console.log(`${signal} received, shutting down...`);
  clearInterval(pollingTimer);
  if (server) {
    await new Promise((resolve) => server.close(resolve));
  }
  await Promise.allSettled(activeDeliveries);
  database.close();
  process.exit(0);
}

if (require.main === module) {
  start();
  ['SIGINT', 'SIGTERM'].forEach((signal) => process.on(signal, () => shutdown(signal)));
}

process.on('unhandledRejection', (reason) => {
  console.error('Unhandled promise rejection:', reason);
});
process.on('uncaughtException', (err) => {
  console.error('Uncaught exception:', err);
  process.exit(1);
});

module.exports = app;

