function retryDelay(attemptCount) {
  const exponentialDelay = Math.min(initialRetryDelayMs * (2 ** (attemptCount - 1)), maxRetryDelayMs);
  return Math.min(Math.round(exponentialDelay * (0.5 + Math.random())), maxRetryDelayMs);
}

